\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{A Stalagmite $\delta^{18}$O Record of Monsoon Variability during
the Last Deglaciation}
\author{Y.~Fontaine, H.~Long, and P.~Iyer}
\date{}

\begin{document}
\maketitle

\begin{abstract}
The transition out of the last glacial period saw abrupt reorganisations
of the Asian monsoon, but regional expressions remain poorly dated. We
present a stalagmite $\delta^{18}$O record from Qinglong Cave in northern
Guizhou that covers 14.7 to 11.2~ka~BP at sub-decadal resolution, anchored
by 26 $^{230}$Th ages.
\end{abstract}

\section{Site and Sample}
Qinglong Cave (27.8$^{\circ}$N, 107.2$^{\circ}$E) is a shallow,
well-ventilated cave developed in Permian limestone on the flank of the
Dalou Mountains. Stalagmite QL-7, a 380~mm candle-shaped sample, was
collected 600~m from the entrance, where drip hydrology is buffered by a
thick epikarst and cave-air $\delta^{18}$O tracks precipitation values on
seasonal timescales.

\section{Chronology and Sampling}
Twenty-six $^{230}$Th ages, with typical uncertainties of $\pm$80 years
(2$\sigma$), constrain an age model built by Monte Carlo interpolation
between dated horizons. For stable-isotope analysis, 412 powder
subsamples were micromilled at 0.5~mm increments along the growth axis.
Across the 3.5~kyr record this sampling yields an average temporal
resolution of about 8.5 years per subsample, finest (4--5 years) between
12.9 and 11.7~ka~BP where growth was fastest.

\section{The Deglacial Signal}
The $\delta^{18}$O series shows a two-step weakening of the monsoon into
the Younger Dryas and a rapid recovery at 11.5~ka~BP, synchronous within
dating uncertainty with records from Hulu and Dongge Caves 300~km to the
southeast. Centennial-scale dry events at 13.9 and 12.3~ka~BP punctuate
the longer trend.

\section{Conclusions}
Stalagmite QL-7 extends the spatial coverage of deglacial monsoon records
to the northern margin of the Guizhou karst and confirms that the
Younger Dryas monsoon minimum was regionally coherent.

\end{document}
